PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, password TEXT NOT NULL, recovery_hash TEXT NOT NULL, created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS networks (id TEXT PRIMARY KEY, name TEXT NOT NULL, code TEXT NOT NULL UNIQUE, owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS memberships (network_id TEXT NOT NULL REFERENCES networks(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, muted INTEGER NOT NULL DEFAULT 0, joined_event INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(network_id,user_id));
CREATE TABLE IF NOT EXISTS rooms (id TEXT PRIMARY KEY, network_id TEXT NOT NULL REFERENCES networks(id) ON DELETE CASCADE, owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, title TEXT NOT NULL, street TEXT NOT NULL, city TEXT NOT NULL, postal_code TEXT NOT NULL, country TEXT NOT NULL, timezone TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', guests INTEGER NOT NULL CHECK(guests BETWEEN 1 AND 20), room_type TEXT NOT NULL DEFAULT 'room' CHECK(room_type IN ('room','home','van')));
CREATE TABLE IF NOT EXISTS periods (id TEXT PRIMARY KEY, room_id TEXT NOT NULL REFERENCES rooms(id) ON DELETE CASCADE, start TEXT NOT NULL, end TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('free','busy')), CHECK(start < end));
CREATE TABLE IF NOT EXISTS stays (id TEXT PRIMARY KEY, room_id TEXT NOT NULL REFERENCES rooms(id) ON DELETE CASCADE, guest_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, start TEXT NOT NULL, end TEXT NOT NULL, guests INTEGER NOT NULL, message TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('pending','accepted','declined','cancelled')), created TEXT NOT NULL, CHECK(start < end));
CREATE TABLE IF NOT EXISTS events (id INTEGER PRIMARY KEY AUTOINCREMENT, network_id TEXT NOT NULL REFERENCES networks(id) ON DELETE CASCADE, actor_id TEXT REFERENCES users(id) ON DELETE SET NULL, recipient_id TEXT REFERENCES users(id) ON DELETE CASCADE, kind TEXT NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL, created TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS events_network ON events(network_id,id);
CREATE INDEX IF NOT EXISTS periods_room ON periods(room_id,start,end);
CREATE INDEX IF NOT EXISTS stays_room ON stays(room_id,status,start,end);
CREATE TABLE IF NOT EXISTS rate_limits (key TEXT PRIMARY KEY, count INTEGER NOT NULL, window INTEGER NOT NULL);

CREATE TABLE IF NOT EXISTS photos (id TEXT PRIMARY KEY, room_id TEXT NOT NULL REFERENCES rooms(id) ON DELETE CASCADE, content BLOB NOT NULL);
